package com.xuhang.mealops.inventory.domain;
import java.util.*; import com.xuhang.mealops.measurement.domain.Quantity;
public final class InventoryConsumptionAllocator {
 public InventoryConsumptionPlan allocate(long ingredientId, Quantity requested, List<InventoryBatch> input){ if(requested==null||requested.amount().signum()<=0) throw new InvalidInventoryBatchException("Requested quantity must be positive"); var batches=input.stream().filter(b->b.ingredientId()==ingredientId&&b.remainingQuantity().unit()==requested.unit()&&b.remainingQuantity().amount().signum()>0).sorted(Comparator.comparing(InventoryBatch::expiresOn,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(InventoryBatch::id)).toList(); var total=batches.stream().map(b->b.remainingQuantity().amount()).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add); if(total.compareTo(requested.amount())<0) throw new InsufficientInventoryException("Insufficient inventory"); var a=new ArrayList<InventoryConsumptionAllocation>(); var remaining=requested.amount(); int p=1; for(var b:batches){var use=remaining.min(b.remainingQuantity().amount()); var after=b.remainingQuantity().amount().subtract(use); a.add(new InventoryConsumptionAllocation(p++,b.id(),b.version(),use,b.remainingQuantity().amount(),after,requested.unit().code())); remaining=remaining.subtract(use); if(remaining.signum()==0)break;} return new InventoryConsumptionPlan(requested,a); }
}
